<?php
namespace App\Application\Payment;
use App\Exceptions\ApiProblem; use App\Models\Payment; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str;
final class FailSimulationPaymentAction { public function execute(Payment $payment,string $status='failed'): Payment { return DB::transaction(function() use($payment,$status): Payment { $p=Payment::query()->whereKey($payment->id)->lockForUpdate()->firstOrFail(); if($p->status==='succeeded') throw new ApiProblem('PAYMENT_ALREADY_PROCESSED','A successful payment cannot be failed or cancelled.',409); if(!in_array($status,['failed','cancelled'],true)) throw new ApiProblem('INVALID_PAYMENT_OUTCOME','Unsupported simulation outcome.',422); $p->update(['status'=>$status,'failed_at'=>$status==='failed'?now():null]); DB::table('payment_events')->insert(['id'=>(string)Str::ulid(),'payment_id'=>$p->id,'event_type'=>'payment.'.$status,'provider_event_id'=>'SIM-EVT-'.Str::upper(Str::random(14)),'payload'=>json_encode(['source'=>'simulation']),'occurred_at'=>now(),'created_at'=>now(),'updated_at'=>now()]); return $p->refresh(); }); } }
